+const quizForm = document.getElementById('quizForm');
+const resultContainer = document.getElementById('resultContainer');
+const resultDetails = document.getElementById('resultDetails');
+
+// Define correct answers for each question
+const correctAnswers = {
+    q1: ['data-science'],
+    q2: ['javascript', 'wasm'],
+    q3: ['cpp', 'rust']
+};
+
+quizForm.addEventListener('submit', function(event) {
+    event.preventDefault();
+    evaluateQuiz();
+});
+
+function evaluateQuiz() {
+    const userAnswers = {
+        q1: getSelectedAnswers('q1'),
+        q2: getSelectedAnswers('q2'),
+        q3: getSelectedAnswers('q3')
+    };
+
+    const results = [];
+    let correctCount = 0;
+    const totalQuestions = 3;
+
+    // Check Q1
+    const q1Correct = areArraysEqual(userAnswers.q1, correctAnswers.q1);
+    if (q1Correct) correctCount++;
+    results.push({
+        number: 1,
+        correct: q1Correct,
+        userAnswers: userAnswers.q1,
+        correctAnswers: correctAnswers.q1,
+        question: 'What is Python primarily used for?'
+    });
+
+    // Check Q2
+    const q2Correct = areArraysEqual(userAnswers.q2, correctAnswers.q2);
+    if (q2Correct) correctCount++;
+    results.push({
+        number: 2,
+        correct: q2Correct,
+        userAnswers: userAnswers.q2,
+        correctAnswers: correctAnswers.q2,
+        question: 'Which languages run natively in web browsers?'
+    });
+
+    // Check Q3
+    const q3Correct = areArraysEqual(userAnswers.q3, correctAnswers.q3);
+    if (q3Correct) correctCount++;
+    results.push({
+        number: 3,
+        correct: q3Correct,
+        userAnswers: userAnswers.q3,
+        correctAnswers: correctAnswers.q3,
+        question: 'Which of these are compiled languages?'
+    });
+
+    displayResults(results, correctCount, totalQuestions);
+}
+
+function getSelectedAnswers(questionName) {
+    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
+    return Array.from(checkboxes).map(cb => cb.value).sort();
+}
+
+function areArraysEqual(arr1, arr2) {
+    if (arr1.length !== arr2.length) return false;
+    return arr1.every((val, idx) => val === arr2[idx]);
+}
+
+function displayResults(results, correctCount, totalQuestions) {
+    let html = `
+        <div class="result-item">
+            <strong>Score: <span class="result-correct">${correctCount}/${totalQuestions}</span> correct</strong>
+        </div>
+    `;
+
+    results.forEach(result => {
+        const status = result.correct ? 'Correct ✓' : 'Incorrect ✗';
+        const statusClass = result.correct ? 'result-correct' : 'result-incorrect';
+        
+        html += `
+            <div class="result-item">
+                <div><span class="result-label">Question ${result.number}:</span></div>
+                <div style="margin-top: 6px; color: #a0afc0;">Question: "${result.question}"</div>
+                <div style="margin-top: 4px; color: #a0afc0;">Your answer: ${formatAnswerList(result.userAnswers) || 'No answer selected'}</div>
+                <div style="margin-top: 4px; color: #a0afc0;">Correct answer: ${formatAnswerList(result.correctAnswers)}</div>
+                <div style="margin-top: 6px;"><span class="${statusClass}">${status}</span></div>
+            </div>
+        `;
+    });
+
+    resultDetails.innerHTML = html;
+    resultContainer.classList.remove('hidden');
+    quizForm.style.display = 'none';
+}
+
+function formatAnswerList(answers) {
+    if (!answers || answers.length === 0) return '';
+    
+    const answerMap = {
+        'data-science': 'Data science and machine learning',
+        'web-frontend': 'Building web frontends',
+        'system-prog': 'Low-level system programming',
+        'game-dev': 'Game development',
+        'javascript': 'JavaScript',
+        'python': 'Python',
+        'java': 'Java',
+        'wasm': 'WebAssembly (via compilation)',
+        'cpp': 'C++',
+        'rust': 'Rust',
+        'ruby': 'Ruby'
+    };
+
+    return answers.map(ans => answerMap[ans] || ans).join(', ');
+}
+
+function resetQuiz() {
+    quizForm.reset();
+    resultContainer.classList.add('hidden');
+    quizForm.style.display = 'flex';
+    window.scrollTo(0, 0);
+}
+
